
"use strict";
// BCCWJ短単位語彙表 ver.1.0 を参照した加工一般語彙 + かな・カタカナ別名を静的統合
/* ================= SANA ENGINES (inlined, deterministic) ================= */
const KANA={ "あ":"a","い":"i","う":"u","え":"e","お":"o","か":"ka","き":"ki","く":"ku","け":"ke","こ":"ko",
"が":"ga","ぎ":"gi","ぐ":"gu","げ":"ge","ご":"go","さ":"sa","し":"shi","す":"su","せ":"se","そ":"so",
"ざ":"za","じ":"ji","ず":"zu","ぜ":"ze","ぞ":"zo","た":"ta","ち":"chi","つ":"tsu","て":"te","と":"to",
"だ":"da","ぢ":"ji","づ":"zu","で":"de","ど":"do","な":"na","に":"ni","ぬ":"nu","ね":"ne","の":"no",
"は":"ha","ひ":"hi","ふ":"fu","へ":"he","ほ":"ho","ば":"ba","び":"bi","ぶ":"bu","べ":"be","ぼ":"bo",
"ぱ":"pa","ぴ":"pi","ぷ":"pu","ぺ":"pe","ぽ":"po","ま":"ma","み":"mi","む":"mu","め":"me","も":"mo",
"や":"ya","ゆ":"yu","よ":"yo","ら":"ra","り":"ri","る":"ru","れ":"re","ろ":"ro","わ":"wa","を":"o","ん":"n",
"きゃ":"kya","きゅ":"kyu","きょ":"kyo","しゃ":"sha","しゅ":"shu","しょ":"sho","ちゃ":"cha","ちゅ":"chu","ちょ":"cho",
"にゃ":"nya","にゅ":"nyu","にょ":"nyo","ひゃ":"hya","ひゅ":"hyu","ひょ":"hyo","みゃ":"mya","みゅ":"myu","みょ":"myo",
"りゃ":"rya","りゅ":"ryu","りょ":"ryo","ぎゃ":"gya","ぎゅ":"gyu","ぎょ":"gyo","じゃ":"ja","じゅ":"ju","じょ":"jo",
"びゃ":"bya","びゅ":"byu","びょ":"byo","ぴゃ":"pya","ぴゅ":"pyu","ぴょ":"pyo" };
function kataToHira(s){return s.replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));}
function hiraToKata(s){return s.replace(/[\u3041-\u3096]/g,c=>String.fromCharCode(c.charCodeAt(0)+0x60));}
function toMora(k){
  let s=kataToHira(k).replace(/[ーｰ]/g,""); const m=[];
  for(let i=0;i<s.length;i++){
    const two=s.substr(i,2);
    if(KANA[two]){m.push(KANA[two]);i++;continue;}
    const c=s[i];
    if(c==="っ")continue;
    if(c==="ん"){ if(m.length)m[m.length-1]+="n"; else m.push("n"); continue; }
    if(KANA[c])m.push(KANA[c]);
  }
  const out=[]; for(const x of m){const p=out[out.length-1];
    if(p&&"aiueo".includes(x)&&p.slice(-1)===x)continue; out.push(x);} return out;
}
function stem(k,seen){
  const m=toMora(k); if(!m.length)return null; seen=seen||new Set();
  const base=m.slice().reverse().join(""); // 読みのモーラを後ろから並べる(日本語に見えず・開音節保持・可逆)
  if(!seen.has(base)) return base;
  for(const v of ["a","i","u","e","o","2","3"]) if(!seen.has(base+v)) return base+v; // 同音衝突のみ区別
  // 大辞書では同音語が8件を超える。4以降を必要なだけ伸ばして必ず一意にする。
  for(let n=4;;n++) if(!seen.has(base+n)) return base+n;
}
const POS={noun:"ro",adj:"li",adv:"ne",verb:"se"};
const DERIV={agent:"to",place:"ba",tool:"ki",result:"mi",abstract:"ra"};
// v1.2: 活用を日本語ローマ字ではなく、予約されたSANA固有標識で表す。
// 語彙語根とはハイフンで境界を明示し、標識順序を固定する。
const MORPH12={
  past:"veta", connective:"veni", stem:"vami", progressive:"vira", casual:"vato",
  volitional:"voro", conditional:"vaka", hypothetical:"veka", listing:"vari", desire:"vaya", polite:"vasa",
  request:"vaku", wish:"veha", passive:"vapa", onward:"vago", excessive:"vagi",
  continuative:"vani", kana:"veki", negativeDe:"vade", appearance:"vosa", causative:"vaca", imperative:"vema", easy:"vayu"
};
function morphToken(base,seq){ return base+(seq&&seq.length?"-"+seq.join("-"):""); }
function deriveWord(root,deriv,pos){let s=root; if(deriv)s+=DERIV[deriv]; s+=POS[pos||"noun"]; return s;}
function conj(root,t){
  const base=root+POS.verb;
  if(t==="neg") return "nu "+base;
  const seq={past:[MORPH12.past],prog:[MORPH12.progressive],pastprog:[MORPH12.progressive,MORPH12.past],vol:[MORPH12.volitional]}[t]||[];
  return morphToken(base,seq);
}
function family(root){return {
  verb:[["辞書",conj(root,"base")],["過去",conj(root,"past")],["否定",conj(root,"neg")],
        ["進行",conj(root,"prog")],["意志",conj(root,"vol")]],
  deriv:[["人 · agent",deriveWord(root,"agent","noun")],["場 · place",deriveWord(root,"place","noun")],
        ["道具 · tool",deriveWord(root,"tool","noun")],["結果 · result",deriveWord(root,"result","noun")],
        ["抽象 · abstract",deriveWord(root,"abstract","noun")],
        ["形容詞",deriveWord(root,null,"adj")],["副詞",deriveWord(root,null,"adv")]]
};}

