/* ---- build runtime dictionary (deterministic roots) ---- */
// v1.3 beta.3: 6SEG上で同一形になる「1」と「-」の判定に使う前置語を、
// エンコーダ側と共有する単一の定義表へ集約する。
// 新しいハイフン前置チャネルはこの表へ追加し、生成側と読取側の双方へ伝播させる。
const SANA_HYPHEN_CHANNELS=Object.freeze({
  negation:"nu",
  asciiLiteral:"lit",
  mixedLiteral:"jpx",
  hiraganaLiteral:"khx",
  katakanaLiteral:"kkx",
  legacyHiraganaLiteral:"kh",
  honorificO:"hono",
  honorificGo:"hongo"
});
const SEG_HYPHEN_PREFIXES=new Set(Object.values(SANA_HYPHEN_CHANNELS));
function isSanaHyphenToken(token){
  const s=String(token||""),cut=s.indexOf("-");
  return cut>0 && SEG_HYPHEN_PREFIXES.has(s.slice(0,cut));
}
const used=new Set(["kono","sono","ano",SANA_HYPHEN_CHANNELS.negation,"na","mu","la","no","te","mo","ga",
  ...Object.values(MORPH12),"cora","core","cori","hesa","hema","hemi"]);
let DICT=[]; // {ja,yomi,pos,role,vstem,root}
const DICT_KEY_INDEX=new Map();
function addRoot(ja,yomi,pos,role,vstem){
  const key=ja+"\u0000"+yomi;
  const old=DICT_KEY_INDEX.get(key);
  if(old){
    // 後続バッチに、より詳しい品詞・語幹情報がある場合は捨てずに補完する。
    if((old.pos==="noun" || !old.pos) && pos && pos!=="noun") old.pos=pos;
    if(!old.role && role) old.role=role;
    if(!old.vstem && vstem) old.vstem=vstem;
    return old;
  }
  const root=stem(yomi,used); if(!root)return null; used.add(root);
  const e={ja,yomi,pos:pos||"noun",role:role||null,vstem:vstem||null,root};
  DICT.push(e); DICT_KEY_INDEX.set(key,e); return e;
}
SEED.forEach(a=>addRoot(a[0],a[1],a[2],a[3],a[4]));

// v1.4 alpha2: 人名「真恵」の表記別名。
// 真恵 / さなえ / サナエは、別々の同音語ではなく同一人物名として
// 一つのSANA語根を共有する。
const SANAE_NAME_ENTRY=addRoot("真恵","さなえ","name",null,null);
if(SANAE_NAME_ENTRY){
  for(const surface of ["さなえ","サナエ"]){
    const yomi="さなえ";
    const key=surface+"\u0000"+yomi;
    if(!DICT_KEY_INDEX.has(key)){
      const alias={
        ja:surface,
        yomi,
        pos:"name",
        role:null,
        vstem:null,
        root:SANAE_NAME_ENTRY.root,
        aliasOf:"真恵"
      };
      DICT.push(alias);
      DICT_KEY_INDEX.set(key,alias);
    }
  }
}
