// 追加語の最終SANAトークンが既存語と衝突しないよう、語根だけでなく
// 品詞語尾を含む基本トークンを確認してから登録する。既存語根は変更しない。
const ADDITIONAL_TOKEN_OCCUPIED=new Set(DICT.map(e=>e.pos==="name"?e.root:e.root+(POS[e.pos]||POS.noun)));
function addRootGuarded(ja,yomi,pos,role,vstem){
  const key=ja+"\u0000"+yomi, old=DICT_KEY_INDEX.get(key);
  if(old){
    if((old.pos==="noun"||!old.pos)&&pos&&pos!=="noun")old.pos=pos;
    if(!old.role&&role)old.role=role; if(!old.vstem&&vstem)old.vstem=vstem; return old;
  }
  const outToken=r=>pos==="name"?r:r+(POS[pos]||POS.noun);
  let root=stem(yomi,used);
  while(root&&ADDITIONAL_TOKEN_OCCUPIED.has(outToken(root))){used.add(root);root=stem(yomi,used);}
  if(!root)return null; used.add(root); ADDITIONAL_TOKEN_OCCUPIED.add(outToken(root));
  const e={ja,yomi,pos:pos||"noun",role:role||null,vstem:vstem||null,root};
  DICT.push(e);DICT_KEY_INDEX.set(key,e);return e;
}

