SEED_V14_ALPHA9.forEach(a=>addRootGuarded(a[0],a[1],a[2],a[3]||null,a[4]||null));

// 読みが確定できる Peripheral Memory の語彙を既存語根の後に追加する。
[
 ["球","きゅう","noun"],["意識化","いしきか","noun"],["点滅","てんめつ","noun"],
 ["仮設","かせつ","noun"],["銀座","ぎんざ","name"],["高松次郎","たかまつじろう","name"],
 ["宮武外骨","みやたけがいこつ","name"],["外骨","がいこつ","name"],
 ["請求項","せいきゅうこう","noun"],["偶然性","ぐうぜんせい","noun"],["即興性","そっきょうせい","noun"],
 ["反芸術","はんげいじゅつ","noun"],["刹那滅","せつなめつ","noun"],["等式","とうしき","noun"]
].forEach(([ja,yomi,pos])=>addRootGuarded(ja,yomi,pos,null,null));

// BCCWJ統合時に名詞として混入した明白な活用断片だけを、語根割当後に除外する。
// 「なます」のような実在名詞は残す。既存語根の割当順は変えない。
const MINED_NOUN_ARTIFACTS=new Set(["ます","ました","にじます","おます"]);
DICT=DICT.filter(e=>{
  if(e.pos!=="noun" || !MINED_NOUN_ARTIFACTS.has(e.ja)) return true;
  DICT_KEY_INDEX.delete(e.ja+"\u0000"+e.yomi); return false;
});

