/* ================= FAMILY GENERATOR UI ================= */
function adjForms(e){
  const s=e.vstem; if(!s) return [[e.ja,"base"]];
  // 形容詞語幹 + すぎる／すぎ も、表層から決定的に生成する。
  // 例: すごい → すごすぎる／すごすぎ、高い → 高すぎる。
  return [[s+"すぎなかった","excessiveNegPast"],[s+"すぎた","excessivePast"],
          [s+"すぎない","excessiveNeg"],[s+"すぎる","excessive"],[s+"すぎ","excessiveStem"],[s+"そう","appearance"],
          [s+"くなかった","negpast"],[s+"かった","past"],[s+"くない","neg"],
          [s+"くて","te"],[s+"く","cont"],[e.ja,"base"]]
    .filter(x=>x[0]).sort((a,b)=>b[0].length-a[0].length);
}
