        addVF(out,st+"たくなかった","desireNegPast"); addVF(out,st+"たかった","desirePast");
        addVF(out,st+"たくない","desireNeg"); addVF(out,st+"たい","desire");
        addVF(out,te+"ください","request"); addVF(out,te+"ほしい","wishRequest");
        const caus=s+F.ng.replace(/ない$/,"せる");
        addVF(out,caus.replace(/る$/,"ていた"),"causativePastProg"); addVF(out,caus.replace(/る$/,"ている"),"causativeProg"); addVF(out,caus.replace(/る$/,"ていく"),"causativeTeIku"); addVF(out,caus.replace(/る$/,"て"),"causativeTe"); addVF(out,caus.replace(/る$/,"た"),"causativePast"); addVF(out,caus,"causative");
        addVF(out,st+"やすかった","easyPast"); addVF(out,st+"やすくて","easyTe"); addVF(out,st+"やすく","easyCont"); addVF(out,st+"やすい","easy");
        addVF(out,s+F.ng,"neg"); addVF(out,s+F.ng.replace(/ない$/,"ず"),"negContinuative"); addVF(out,s+F.vo,"vol"); addVF(out,s+F.hy.slice(0,-1),"imperative"); addVF(out,s+F.hy,"hypothetical"); addVF(out,s+F.pa+"ら","conditional"); addVF(out,s+F.pa+"り","tari"); addVF(out,s+F.pa,"past");
        addVF(out,te,"te"); addVF(out,st,"stem");
