["過ぎる","駆ける","みちる","伏せる","ふせる","表わせる","言い表わせる","熟せる","蹌踉ける","ぶっちゃける","嗾ける","諫める","辱しめる","擬える","荒げる","あらげる","える","つめる","につめる","のめる","あるける","きせる","しめる","ねる","にえる","にせる","たける","かえる","おだてる","ふける","もちえる","応える"].forEach(v=>ICHIDAN.add(v));
ICHIDAN_BCCWJ_GENERAL.forEach(v=>ICHIDAN.add(v));
self.onmessage=({data})=>{try{self.postMessage({id:data.id,lines:data.lines.map(ja=>({ja,sana:chunksToSana(translate(ja))}))})}catch(e){self.postMessage({id:data.id,error:String(e)})}};
